package com.harajalakhdar.app;
import android.os.Bundle; import android.graphics.Color; import android.view.Gravity; import android.widget.*; import androidx.appcompat.app.AppCompatActivity;
public class MainActivity extends AppCompatActivity { public void onCreate(Bundle b){super.onCreate(b); LinearLayout r=new LinearLayout(this); r.setOrientation(LinearLayout.VERTICAL); r.setPadding(30,50,30,30); TextView t=new TextView(this); t.setText("حراج الأخضر"); t.setTextSize(30); t.setTextColor(Color.rgb(22,130,59)); t.setGravity(Gravity.CENTER); r.addView(t); TextView w=new TextView(this); w.setText("حراجك السعودي للبيع والشراء"); w.setTextSize(19); w.setGravity(Gravity.CENTER); r.addView(w); EditText s=new EditText(this); s.setHint("ابحث عن إعلان..."); r.addView(s); Button a=new Button(this); a.setText("إضافة إعلان"); r.addView(a); Button l=new Button(this); l.setText("تسجيل الدخول بالبريد الإلكتروني"); r.addView(l); setContentView(r); }}
